// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, Img, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadDMSans = makeLoadFont('DMSans');

// Initialize font loading outside the component render tree
const { fontFamily: dmSansFamily } = loadDMSans();

// Precise uploaded assets for the pixelated and realistic rubber ducks
const PIXEL_DUCK_URL = "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/assets/f346882f46c84543b41e7e80a0e049f1.png";
const RUBBER_DUCK_URL = "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/assets/643aa2a0c65f40848d52d145943a1976.png";

// Stationary / drifting bubbles under water
const BUBBLES = [
  { xRel: 0.15, yRel: 0.75, size: 6, speed: 0.8, delay: 0.2 },
  { xRel: 0.28, yRel: 0.85, size: 4, speed: 0.5, delay: 0.7 },
  { xRel: 0.42, yRel: 0.70, size: 8, speed: 1.1, delay: 0.1 },
  { xRel: 0.55, yRel: 0.90, size: 5, speed: 0.6, delay: 0.5 },
  { xRel: 0.73, yRel: 0.78, size: 7, speed: 0.9, delay: 0.3 },
  { xRel: 0.88, yRel: 0.82, size: 5, speed: 0.7, delay: 0.9 },
  { xRel: 0.05, yRel: 0.88, size: 5, speed: 0.6, delay: 0.4 },
  { xRel: 0.35, yRel: 0.80, size: 6, speed: 0.8, delay: 0.0 },
  { xRel: 0.65, yRel: 0.72, size: 7, speed: 1.0, delay: 0.6 },
  { xRel: 0.92, yRel: 0.92, size: 4, speed: 0.5, delay: 0.2 },
];



export type DuckLoadingProps = Record<string, any>;

const DuckLoading: React.FC<DuckLoadingProps> = ({
  backgroundColor = "#5cc2f2",
  transparentBackground = true,
  durationInSeconds = 8,
  bobAmplitude = 16,
  waveCycles = 1.5,
  maxRotation = 4,
  duckSize = 140,
  rippleColor = "#ffffff",
  skyColorTop = "#5cc2f2",
  skyColorBottom = "#aee4ff",
  waterColorTop = "#0099ff",
  waterColorBottom = "#0055b3",
  phrases = [
    "You can leave this page...",
    "Rendering will continue in the background...",
    " We’ll save it when it’s ready...",
    "Come back anytime...",
  ],
  textColor = "#000000",
  fontSize = 79,
  letterSpacing = -5,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const t = frame / fps;
  // Standard loop period is 2 seconds if even duration; otherwise 1 second to stay perfectly seamless
  const period = durationInSeconds % 2 === 0 ? 2.0 : 1.0;

  // Wave horizontal propagation speeds & phases
  const phase1 = 2 * Math.PI * (t / period);
  const phase2 = -2 * Math.PI * (t / period) + Math.PI * 0.5;
  const phase3 = 2 * Math.PI * (t / period) + Math.PI;

  // Generate a closed wave path filling down to the bottom of the canvas
  const getWavePath = (
    baseY: number,
    amplitude: number,
    cycles: number,
    phaseShift: number,
    w: number,
    h: number
  ) => {
    const points: string[] = [];
    const segments = 60;
    for (let i = 0; i <= segments; i++) {
      const ratio = i / segments;
      const x = ratio * w;
      const angle = ratio * Math.PI * 2 * cycles + phaseShift;
      const y = baseY + Math.sin(angle) * amplitude;
      if (i === 0) {
        points.push(`M ${x} ${y}`);
      } else {
        points.push(`L ${x} ${y}`);
      }
    }
    points.push(`L ${w} ${h}`);
    points.push(`L 0 ${h}`);
    points.push("Z");
    return points.join(" ");
  };

  // Generate an open wave path for clean top highlight strokes
  const getWaveLinePath = (
    baseY: number,
    amplitude: number,
    cycles: number,
    phaseShift: number,
    w: number
  ) => {
    const points: string[] = [];
    const segments = 60;
    for (let i = 0; i <= segments; i++) {
      const ratio = i / segments;
      const x = ratio * w;
      const angle = ratio * Math.PI * 2 * cycles + phaseShift;
      const y = baseY + Math.sin(angle) * amplitude;
      if (i === 0) {
        points.push(`M ${x} ${y}`);
      } else {
        points.push(`L ${x} ${y}`);
      }
    }
    return points.join(" ");
  };

  // Water level layers matching reference layout
  const backWavePath = getWavePath(height * 0.58, 12, waveCycles, phase1, width, height);
  const middleWavePath = getWavePath(height * 0.60, 15, waveCycles, phase2, width, height);
  const frontWaveClosedPath = getWavePath(height * 0.63, bobAmplitude, waveCycles, phase3, width, height);
  const frontWaveLinePath = getWaveLinePath(height * 0.63, bobAmplitude, waveCycles, phase3, width);

  // Background sky styling
  const skyBg = transparentBackground
    ? "transparent"
    : `linear-gradient(to bottom, ${skyColorTop}, ${skyColorBottom})`;

  // Configuration for 6 ducks
  const numDucks = 6;
  const margin = width * 0.1;
  const availableWidth = width - 2 * margin;

  // Concentric floating ripple waves
  const ripples = Array.from({ length: numDucks }).map((_, i) => {
    const x_i = margin + (i / (numDucks - 1)) * availableWidth;
    const angle_i = phase3 + (x_i / width) * Math.PI * 2 * waveCycles;
    
    let ripplePhase = (angle_i + Math.PI * 0.5) % (Math.PI * 2);
    if (ripplePhase < 0) {
      ripplePhase += Math.PI * 2;
    }
    const rippleProgress = ripplePhase / (Math.PI * 2);

    // Ripple 1
    const progress1 = rippleProgress;
    const rx1 = progress1 * (duckSize * 0.6);
    const ry1 = rx1 * 0.22; // Squashed perspective ratio
    const opacity1 = Math.max(0, (1 - progress1) * 0.7);

    // Ripple 2 (staggered phase shift)
    const progress2 = (rippleProgress + 0.5) % 1.0;
    const rx2 = progress2 * (duckSize * 0.6);
    const ry2 = rx2 * 0.22;
    const opacity2 = Math.max(0, (1 - progress2) * 0.7);

    // Vertical anchor exactly tracking wave height
    const duckY = (height * 0.63) + Math.sin(angle_i) * bobAmplitude;

    return (
      <g key={`ripple-${i}`}>
        {opacity1 > 0 && (
          <ellipse
            cx={x_i}
            cy={duckY + duckSize * 0.12}
            rx={rx1}
            ry={ry1}
            stroke={rippleColor}
            strokeWidth={2}
            fill="none"
            opacity={opacity1}
            style={{ transition: "none" }}
          />
        )}
        {opacity2 > 0 && (
          <ellipse
            cx={x_i}
            cy={duckY + duckSize * 0.12}
            rx={rx2}
            ry={ry2}
            stroke={rippleColor}
            strokeWidth={1.5}
            fill="none"
            opacity={opacity2}
            style={{ transition: "none" }}
          />
        )}
      </g>
    );
  });

  // Render ducks layer
  const ducks = Array.from({ length: numDucks }).map((_, i) => {
    const x_i = margin + (i / (numDucks - 1)) * availableWidth;
    const angle_i = phase3 + (x_i / width) * Math.PI * 2 * waveCycles;
    const duckY = (height * 0.63) + Math.sin(angle_i) * bobAmplitude;
    
    // Physics slope derivative of the sine wave for rotating
    const slope = Math.cos(angle_i);
    const rotation = slope * maxRotation;
    
    const isPixel = i % 2 === 0;
    const duckSrc = isPixel ? PIXEL_DUCK_URL : RUBBER_DUCK_URL;

    // Soft organic squish and stretch
    const scaleY = 1.0 + Math.sin(angle_i) * 0.04;
    const scaleX = 1.0 - Math.sin(angle_i) * 0.02;

    return (
      <div
        key={`duck-${i}`}
        style={{
          position: "absolute",
          left: x_i - duckSize / 2,
          top: duckY - duckSize * 0.76, // partially submerged
          width: duckSize,
          height: duckSize,
          transform: `rotate(${rotation}deg) scale(${scaleX}, ${scaleY})`,
          transformOrigin: "bottom center",
          transition: "none",
          zIndex: 30,
        }}
      >
        <Img
          src={duckSrc}
          style={{
            width: "100%",
            height: "100%",
            objectFit: "contain",
            transition: "none",
          }}
        />
      </div>
    );
  });

  // Floating ambient water bubbles
  const bubblesRender = BUBBLES.map((bubble, idx) => {
    const y_drift = (t * bubble.speed + bubble.delay) % 1.0;
    const opacity = Math.sin(y_drift * Math.PI) * 0.5;
    const x = bubble.xRel * width + Math.sin(2 * Math.PI * y_drift) * 12;
    const y = (0.62 + (1 - y_drift) * 0.35) * height;

    return (
      <div
        key={`bubble-${idx}`}
        style={{
          position: "absolute",
          left: x,
          top: y,
          width: bubble.size,
          height: bubble.size,
          borderRadius: "50%",
          backgroundColor: "#ffffff",
          opacity,
          zIndex: 45,
          pointerEvents: "none",
          transition: "none",
        }}
      />
    );
  });

  // Phrase rotation and transition logic
  const numPhrases = phrases.length;
  const phraseDuration = numPhrases > 0 ? durationInSeconds / numPhrases : 1;
  const activePhraseIndex = numPhrases > 0 ? Math.floor(t / phraseDuration) % numPhrases : 0;
  const activePhrase = numPhrases > 0 ? phrases[activePhraseIndex] : "";
  const phraseProgress = t % phraseDuration;

  // Compute fade in, hold, and fade out with slight upward drift
  const opacity = interpolate(
    phraseProgress,
    [0, phraseDuration * 0.15, phraseDuration * 0.85, phraseDuration],
    [0, 1, 1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const driftY = interpolate(
    phraseProgress,
    [0, phraseDuration * 0.15, phraseDuration * 0.85, phraseDuration],
    [15, 0, 0, -15],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill style={{ background: skyBg, transition: "none", overflow: "hidden" }}>
      {/* Revolving Phrase Text Layer */}
      {activePhrase && (
        <div
          style={{
            position: "absolute",
            top: height * 0.22,
            left: 0,
            right: 0,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            fontFamily: dmSansFamily,
            fontSize,
            color: textColor,
            fontWeight: "bold",
            letterSpacing: `${letterSpacing}px`,
            zIndex: 5,
            textShadow: "0 4px 12px rgba(0,0,0,0.15)",
            opacity,
            transform: `translateY(${driftY}px)`,
            transition: "none",
            textAlign: "center",
            padding: "0 40px",
          }}
        >
          {activePhrase}
        </div>
      )}

      {/* Back & Middle Waves SVG */}
      <svg
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          width: "100%",
          height: "100%",
          zIndex: 10,
          pointerEvents: "none",
        }}
      >
        <path d={backWavePath} fill="#199be9" style={{ transition: "none" }} />
        <path d={middleWavePath} fill="#0a8cd9" style={{ transition: "none" }} />
      </svg>

      {/* Ripples SVG Layer */}
      <svg
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          width: "100%",
          height: "100%",
          zIndex: 20,
          pointerEvents: "none",
        }}
      >
        {ripples}
      </svg>

      {/* Floating Ducks */}
      {ducks}

      {/* Foreground Wave & Top Crest Highlight */}
      <svg
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          width: "100%",
          height: "100%",
          zIndex: 40,
          pointerEvents: "none",
        }}
      >
        <defs>
          <linearGradient id="waterGradient" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor={waterColorTop} />
            <stop offset="100%" stopColor={waterColorBottom} />
          </linearGradient>
        </defs>
        <path d={frontWaveClosedPath} fill="url(#waterGradient)" style={{ transition: "none" }} />
        <path
          d={frontWaveLinePath}
          fill="none"
          stroke="#3cd2ff"
          strokeWidth={6}
          strokeLinecap="round"
          style={{ transition: "none" }}
        />
      </svg>

      {/* Foreground Drifting Bubbles */}
      {bubblesRender}
    </AbsoluteFill>
  );
};

export default DuckLoading;